import{_ as a,o as e,c as r,a3 as d}from"./chunks/framework.CWYzGJW1.js";const c=JSON.parse('{"title":"模型建議 (含繁體中文)","description":"挑模型先看記憶體放不放得下, 再看授權, 最後才看能力.","frontmatter":{"description":"挑模型先看記憶體放不放得下, 再看授權, 最後才看能力."},"headers":[],"relativePath":"ref/models.md","filePath":"ref/models.md","lastUpdated":1793064460000}'),l={name:"ref/models.md"};function o(i,t,n,g,h,m){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="模型建議-含繁體中文" tabindex="-1">模型建議 (含繁體中文) <a class="header-anchor" href="#模型建議-含繁體中文" aria-label="Permalink to &quot;模型建議 (含繁體中文)&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: 參考資料</li><li>實機驗證: 未進行 (需實機確認: 各等級模型的實際記憶體用量與繁體中文表現)</li></ul></div><p><strong>結論</strong>: 挑模型先看記憶體放不放得下, 再看授權, 最後才看能力. 8 至 12GB 顯示記憶體可從 8B 級模型開始; 16GB 放約 14B 級餘裕較大 (與 K3.1 節一致); 24B 至 32B 級要 24GB 以上, 其中 30B 級在 24GB 時上下文須壓低. 需要繁體中文表現時, TAIDE 與聯發創新基地的 Breeze 2 是以繁體中文資料訓練的選項, 但授權各有條件; 國際模型的模型卡多半沒有繁體中文評測, 導入前請用自己的題目實測.</p><div class="tip custom-block"><p class="custom-block-title">本頁常見名詞</p><table tabindex="0"><thead><tr><th>詞</th><th>意思</th></tr></thead><tbody><tr><td>模型卡 (model card)</td><td>模型發布頁上的說明文件, 寫明參數量, 授權, 支援語言與評測</td></tr><tr><td>參數量 (B)</td><td>模型的大小, 8B 約 80 億個參數 (見 <a href="/lanai-handbook/know/k1-basics">K1</a>)</td></tr><tr><td>量化 (Q4_K_M 等)</td><td>把模型存得粗一點, 檔案變小; Q4_K_M 是常見的 4 位元 GGUF 格式 (見 <a href="/lanai-handbook/know/k2-quantization">K2</a>)</td></tr><tr><td>MoE (混合專家)</td><td>每次只啟用一部分參數的模型; 速度較快, 但權重仍要全部放進記憶體</td></tr><tr><td>gated model</td><td>下載前須登入並同意條款的模型</td></tr><tr><td><code>trust_remote_code</code></td><td>載入模型時執行模型倉庫附帶的程式碼, 須先審查 (見 <a href="/lanai-handbook/build/m3-model-intake">M3</a>)</td></tr></tbody></table><p>完整詞彙見<a href="/lanai-handbook/ref/glossary">術語對照</a>.</p></div><h2 id="依硬體等級-先算放不放得下" tabindex="-1">依硬體等級: 先算放不放得下 <a class="header-anchor" href="#依硬體等級-先算放不放得下" aria-label="Permalink to &quot;依硬體等級: 先算放不放得下&quot;">​</a></h2><p>挑模型像搬家前量家具: 先確認放得進去, 再談好不好用. 下表把本手冊的硬體等級 (定義見<a href="/lanai-handbook/start/usage">使用說明</a>與 <a href="/lanai-handbook/know/k3-hardware">K3.1 節</a>) 對應到可以起步的模型. 「4 位元權重約」一欄依 K3 的算式估算: 參數量 x 4.8944 位元 / 8 (llama.cpp 以 Llama-3.1-8B 量測的 Q4_K_M 平均位元數, 套用到其他模型為近似). 這只是權重大小, 實際還要加上 KV cache 與執行環境, 所以記憶體要留餘裕 (推論, 信心: 中).</p><table tabindex="0"><thead><tr><th>等級</th><th>記憶體條件</th><th>起步模型</th><th>參數量</th><th>4 位元權重約</th><th>授權</th></tr></thead><tbody><tr><td>A</td><td>無獨立顯示卡</td><td><a href="https://huggingface.co/microsoft/Phi-4-mini-instruct/blob/main/README.md" target="_blank" rel="noreferrer">microsoft/Phi-4-mini-instruct</a></td><td>3.8B</td><td>2.3GB</td><td>MIT</td></tr><tr><td>A</td><td>同上</td><td><a href="https://huggingface.co/google/gemma-4-E2B-it" target="_blank" rel="noreferrer">google/gemma-4-E2B-it</a></td><td>有效 2.3B (含嵌入層 5.1B)</td><td>3.1GB (以 5.1B 計)</td><td>Apache 2.0</td></tr><tr><td>B</td><td>8 至 12GB 顯示記憶體</td><td><a href="https://huggingface.co/meta-llama/Llama-3.1-8B-Instruct" target="_blank" rel="noreferrer">meta-llama/Llama-3.1-8B-Instruct</a></td><td>8B</td><td>4.9GB</td><td>Llama 3.1 Community License</td></tr><tr><td>B</td><td>同上 (繁體中文)</td><td><a href="https://huggingface.co/MediaTek-Research/Llama-Breeze2-8B-Instruct" target="_blank" rel="noreferrer">MediaTek-Research/Llama-Breeze2-8B-Instruct</a></td><td>8B</td><td>4.9GB</td><td>Llama 3.2 Community License</td></tr><tr><td>C</td><td>Apple Silicon 16GB</td><td>同等級 B</td><td>-</td><td>-</td><td>-</td></tr><tr><td>D</td><td>16GB 顯示記憶體 (或 Apple Silicon 32GB 以上)</td><td><a href="https://huggingface.co/taide/Gemma-3-TAIDE-12b-Chat-2602" target="_blank" rel="noreferrer">taide/Gemma-3-TAIDE-12b-Chat-2602</a> (繁體中文)</td><td>12.4B</td><td>7.6GB</td><td>(Gemma 版次)-TAIDE 模型授權條款</td></tr><tr><td>D</td><td>同上</td><td><a href="https://huggingface.co/google/gemma-4-12B-it" target="_blank" rel="noreferrer">google/gemma-4-12B-it</a></td><td>11.95B</td><td>7.3GB</td><td>Apache 2.0</td></tr><tr><td>D</td><td>同上</td><td><a href="https://huggingface.co/openai/gpt-oss-20b" target="_blank" rel="noreferrer">openai/gpt-oss-20b</a></td><td>21B, 每 token 啟用 3.6B (MoE)</td><td>模型卡稱 MoE 權重以 MXFP4 (一種 4 位元浮點量化格式) 訓練後量化, 可在 16GB 記憶體內執行</td><td>Apache 2.0</td></tr><tr><td>E</td><td>24GB 以上, 未滿 48GB 顯示記憶體</td><td><a href="https://huggingface.co/mistralai/Mistral-Small-3.2-24B-Instruct-2506" target="_blank" rel="noreferrer">mistralai/Mistral-Small-3.2-24B-Instruct-2506</a></td><td>24B</td><td>14.7GB</td><td>Apache 2.0</td></tr><tr><td>E</td><td>同上</td><td>Gemma 4 26B A4B (見 <a href="https://huggingface.co/google/gemma-4-31B-it" target="_blank" rel="noreferrer">Gemma 4 模型卡</a>)</td><td>25.2B, 每 token 啟用 3.8B (MoE)</td><td>15.4GB</td><td>Apache 2.0</td></tr><tr><td>E</td><td>同上</td><td><a href="https://huggingface.co/ibm-granite/granite-4.0-h-small" target="_blank" rel="noreferrer">ibm-granite/granite-4.0-h-small</a></td><td>32B, 每 token 啟用 9B (MoE)</td><td>19.6GB</td><td>Apache 2.0</td></tr><tr><td>E</td><td>同上</td><td><a href="https://huggingface.co/google/gemma-4-31B-it" target="_blank" rel="noreferrer">google/gemma-4-31B-it</a></td><td>30.7B</td><td>18.8GB</td><td>Apache 2.0</td></tr><tr><td>F</td><td>48GB 以上或多卡; 此模型須 80GB</td><td>gpt-oss-120b (見 <a href="https://huggingface.co/openai/gpt-oss-20b" target="_blank" rel="noreferrer">gpt-oss-20b 模型卡</a>)</td><td>117B, 每 token 啟用 5.1B (MoE)</td><td>模型卡稱可放進單張 80GB GPU</td><td>Apache 2.0</td></tr></tbody></table><p>資料來源: 參數量, 授權與記憶體說明取自各模型的 Hugging Face 模型卡 (2026-10-27 擷取); 4 位元權重為整理者依上述算式推算. 等級與模型的對應為整理者推論 (信心: 中), 與 <a href="/lanai-handbook/know/k3-hardware">K3.1 節</a>的估算一致: B 級放 8B 級餘裕較大, D 級放約 14B 級餘裕較大, 約 30B 以上通常放不下 16GB. E 級中約 30B 至 32B 級的模型 (權重約 18.4 至 19.6GB) 在 24GB 時已接近或超過 K2 建議的八成上限 (約 19.2GB), 上下文須壓低, 或改用 32GB 以上的配置.</p><p>由上表可見, 每升一個等級, 可選的模型大約大一倍. 等級 F 在 48GB 時可讓一個約 30B 至 35B 級的模型保留充足的上下文並服務多人; 同時常駐多個這類模型, 或跑約 70B 級, 需要 64GB 至 96GB 以上 (見 <a href="/lanai-handbook/know/k3-hardware">K3.1 節</a>與 K3.4 節, 推論). 實際挑選時要再看三件事:</p><ul><li><strong>授權</strong>: Llama, Gemma (TAIDE 沿用) 的自訂授權各有條件, 對外提供服務前請依 <a href="/lanai-handbook/know/k4-licenses">K4</a> 與<a href="/lanai-handbook/ref/licenses">授權速查</a>檢查. Apache 2.0 與 MIT 的限制最少.</li><li><strong>MoE 的取捨</strong>: MoE 模型每次只啟用一小部分參數, 產生文字較快, 但權重仍要全部放進記憶體, 容量以總參數計 (見 <a href="/lanai-handbook/know/k3-hardware">K3.4 節</a>).</li><li><strong>工具呼叫</strong>: 要讓模型操作工具時, 另看 <a href="/lanai-handbook/know/k5-tools-agents">K5</a> 的 BFCL 分數; 通用小模型的多輪表現普遍偏低.</li></ul><p>30B 至 35B 級模型的細部比較 (層數, 上下文, KV cache 用量) 見 <a href="/lanai-handbook/know/k3-hardware">K3.4 節</a>; 資安用途的小型分類與檢索模型 (提示注入偵測, 個資偵測等) 見<a href="/lanai-handbook/decide/model-selection">開源模型選型</a>; 嵌入與重排序模型見 <a href="/lanai-handbook/build/m4-retrieval">M4</a>.</p><h2 id="繁體中文-模型卡有寫才算數" tabindex="-1">繁體中文: 模型卡有寫才算數 <a class="header-anchor" href="#繁體中文-模型卡有寫才算數" aria-label="Permalink to &quot;繁體中文: 模型卡有寫才算數&quot;">​</a></h2><p>多數國際模型以英文為主要訓練語言, 模型卡上的「支援語言」清單差異很大, 而且「支援中文」通常沒有區分簡體與繁體. 判斷繁體中文能力時, 本手冊只採用模型卡或官方文件明載的內容, 其餘以自己的題目實測為準.</p><h3 id="以繁體中文資料訓練的模型" tabindex="-1">以繁體中文資料訓練的模型 <a class="header-anchor" href="#以繁體中文資料訓練的模型" aria-label="Permalink to &quot;以繁體中文資料訓練的模型&quot;">​</a></h3><p><strong>TAIDE</strong> 是以繁體中文資料訓練的台灣模型系列, 在 Hugging Face 的 taide 組織下發布. 目前最新的對話模型是 Gemma-3-TAIDE-12b-Chat-2602, 以 google/gemma-3-12b-pt 為基底, 約 12.4B 參數, 上下文 128K; 模型卡說明以約 220 億個繁體中文 token 持續預訓練, 並在 NVIDIA H200 上訓練 1,520 GPU 小時. 輸入只接受文字. 模型卡自報 TMMLU+ 平均 58.02, 同表的 Gemma-3-12b-it 為 53.82; 台灣地理與台灣用語兩個子科目分別為 70.05 與 76.11 (來源: 模型卡自報, 2026-10-27 擷取; TMMLU+ 的讀法見<a href="/lanai-handbook/ref/benchmarks">基準分數</a>).</p><p>取得方式: 模型為 gated model, 須登入 Hugging Face 並接受「(Gemma 版次)-TAIDE 模型授權條款」才能下載, 另附個人資料蒐集告知. 模型卡提供 transformers 與 vLLM 的載入範例, 建議以 bfloat16 執行. 國研院 TAIDE 網站公布的 Gemma-TAIDE 條款授予非專屬, 全球, 無償的使用授權, 條文未設使用者數或營收門檻; 散布時須附 Gemma Terms of Use 聲明並標示源自 TAIDE, 不得用於軍事或非法目的, 條款修訂於發布時立即生效. 條款要點與連結見<a href="/lanai-handbook/ref/licenses">授權速查</a>. 同一組織也發布 Llama-3.1-TAIDE-LX-8B-Chat 等較早版本, 以及以台灣法規文本微調的嵌入模型 embeddinggemma-GTAIDE-300m-2605 (見<a href="/lanai-handbook/ref/benchmarks">基準分數</a>的例子).</p><p><strong>Breeze 2</strong> 是聯發創新基地 (MediaTek Research) 以 Llama 3.2 為基底, 以繁體中文資料持續預訓練的模型系列, 有 3B 與 8B 兩種大小, 並加入影像理解與函式呼叫能力 (來源: Breeze 2 論文 arXiv 2501.13921). 模型卡標示授權為 Llama 3.2 Community License. 要注意的是, 模型卡的載入範例須開啟 <code>trust_remote_code</code>, 函式呼叫還須搭配聯發創新基地的 <code>mtkresearch</code> 套件; 依 <a href="/lanai-handbook/build/m3-model-intake">M3</a> 的入庫流程, 須先審查模型倉庫附帶的程式碼才能使用. 模型卡本身沒有列出評測分數.</p><h3 id="國際模型的中文支援-依模型卡" tabindex="-1">國際模型的中文支援 (依模型卡) <a class="header-anchor" href="#國際模型的中文支援-依模型卡" aria-label="Permalink to &quot;國際模型的中文支援 (依模型卡)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>模型卡對語言的說明</th></tr></thead><tbody><tr><td>Phi-4-mini-instruct</td><td>列出 23 種語言, 含中文; 同時說明英文以外的語言表現較差</td></tr><tr><td>Llama-3.1-8B-Instruct</td><td>正式支援 8 種語言, 不含中文; 說明訓練資料涵蓋更多語言</td></tr><tr><td>Gemma 4 系列</td><td>開箱支援 35 種以上語言, 以 140 種以上語言預訓練; 未列出語言清單</td></tr><tr><td>granite-4.0-h-small</td><td>列出 12 種語言, 含中文</td></tr><tr><td>Mistral-Small-3.2-24B</td><td>標示 24 種語言, 未列出清單</td></tr><tr><td>gpt-oss-20b / 120b</td><td>模型卡未說明支援語言</td></tr></tbody></table><p>資料來源: 各模型的 Hugging Face 模型卡 (2026-10-27 擷取). 由上表可見, 國際模型即使列出中文, 也沒有區分簡體與繁體, 更沒有繁體中文評測. 需要繁體中文輸出的應用, 建議在 TAIDE 或 Breeze 2 與一個國際模型之間, 用自己的 50 題 (做法同 <a href="/lanai-handbook/build/m4-retrieval">M4.3 節</a>) 比較用詞是否符合台灣習慣與答案是否正確 (整理者建議, 信心: 中).</p><h2 id="參考來源" tabindex="-1">參考來源 <a class="header-anchor" href="#參考來源" aria-label="Permalink to &quot;參考來源&quot;">​</a></h2><p>模型卡 (官方, 2026-10-27 擷取):</p><ul><li><a href="https://huggingface.co/microsoft/Phi-4-mini-instruct/blob/main/README.md" target="_blank" rel="noreferrer">Hugging Face 模型卡: microsoft/Phi-4-mini-instruct</a></li><li><a href="https://huggingface.co/google/gemma-4-E2B-it" target="_blank" rel="noreferrer">Hugging Face 模型卡: google/gemma-4-E2B-it</a></li><li><a href="https://huggingface.co/google/gemma-4-31B-it" target="_blank" rel="noreferrer">Hugging Face 模型卡: google/gemma-4-31B-it</a> (Gemma 4 家族表: E2B, E4B, 12B, 26B A4B, 31B)</li><li><a href="https://huggingface.co/google/gemma-4-12B-it" target="_blank" rel="noreferrer">Hugging Face 模型卡: google/gemma-4-12B-it</a> (Google 發布, Apache 2.0, 11.95B 參數, 基底為 google/gemma-4-12B; 2026-10-27 擷取)</li><li><a href="https://huggingface.co/meta-llama/Llama-3.1-8B-Instruct" target="_blank" rel="noreferrer">Hugging Face 模型卡: meta-llama/Llama-3.1-8B-Instruct</a></li><li><a href="https://huggingface.co/openai/gpt-oss-20b" target="_blank" rel="noreferrer">Hugging Face 模型卡: openai/gpt-oss-20b</a> (含 gpt-oss-120b 的參數與記憶體說明)</li><li><a href="https://huggingface.co/mistralai/Mistral-Small-3.2-24B-Instruct-2506" target="_blank" rel="noreferrer">Hugging Face 模型卡: mistralai/Mistral-Small-3.2-24B-Instruct-2506</a></li><li><a href="https://huggingface.co/ibm-granite/granite-4.0-h-small" target="_blank" rel="noreferrer">Hugging Face 模型卡: ibm-granite/granite-4.0-h-small</a></li></ul><p>繁體中文模型:</p><ul><li><a href="https://huggingface.co/taide/Gemma-3-TAIDE-12b-Chat-2602" target="_blank" rel="noreferrer">Hugging Face 模型卡: taide/Gemma-3-TAIDE-12b-Chat-2602</a> (授權名稱, 取得方式, 訓練資料, TMMLU+ 自報分數)</li><li><a href="https://taide.stpi.niar.org.tw/public/download-model" target="_blank" rel="noreferrer">國研院 TAIDE 模型下載與授權條款頁 (Gemma-TAIDE 條款全文)</a></li><li><a href="https://huggingface.co/taide" target="_blank" rel="noreferrer">Hugging Face: taide 組織頁</a> (TAIDE 模型清單)</li><li><a href="https://huggingface.co/taide/embeddinggemma-GTAIDE-300m-2605" target="_blank" rel="noreferrer">Hugging Face 模型卡: taide/embeddinggemma-GTAIDE-300m-2605</a></li><li><a href="https://huggingface.co/MediaTek-Research/Llama-Breeze2-8B-Instruct" target="_blank" rel="noreferrer">Hugging Face 模型卡: MediaTek-Research/Llama-Breeze2-8B-Instruct</a> (授權, <code>trust_remote_code</code>, 函式呼叫)</li><li><a href="https://huggingface.co/collections/MediaTek-Research/breeze-2-family-67863158443a06a72dd29900" target="_blank" rel="noreferrer">Hugging Face: Breeze 2 模型集合</a></li><li><a href="https://arxiv.org/abs/2501.13921" target="_blank" rel="noreferrer">Hsu 等人, The Breeze 2 Herd of Models (arXiv 2501.13921)</a></li><li><a href="https://www.ithome.com.tw/news/167427" target="_blank" rel="noreferrer">iThome: 聯發創新基地開源 Breeze 2 (2025-02-17)</a> (3B 與 8B 的定位)</li></ul><p>算式依據:</p><ul><li>4 位元權重的位元數: <a href="https://github.com/ggml-org/llama.cpp/blob/master/tools/quantize/README.md" target="_blank" rel="noreferrer">llama.cpp: quantize README</a>, 算式見 <a href="/lanai-handbook/know/k3-hardware">K3.4 節</a></li></ul><p>整理者判斷 (無外部來源):</p><ul><li>硬體等級與模型的對應, 4 位元權重的推算值, 「每升一級可選模型約大一倍」, 繁體中文的實測建議, 為整理者推論.</li><li>文中的類比 (搬家前量家具): 整理者所寫, 無外部來源, 不應當作技術定義引用.</li></ul>',29)])])}const f=a(l,[["render",o]]);export{c as __pageData,f as default};
